/**
 * Shopping Cart & Shipping Options Simulator
 * -------------------------------------------
 * Demonstrates:
 *   - Cart with add/remove/update operations
 *   - Shipping option selection
 *   - Out-of-stock item detection and removal
 *   - Order summary with totals
 */

// ── Shipping Options ─────────────────────────────────────────────

const ShippingMethods = {
  STANDARD:  { id: "STANDARD",  description: "Standard Shipping (5-7 business days)", cost: 4.99 },
  EXPRESS:   { id: "EXPRESS",   description: "Express Shipping (2-3 business days)",   cost: 9.99 },
  OVERNIGHT: { id: "OVERNIGHT", description: "Overnight Shipping (1 business day)",    cost: 19.99 },
  FREE:      { id: "FREE",     description: "Free Shipping (7-10 business days)",      cost: 0.00 },
};

// ── Cart Item ────────────────────────────────────────────────────

function createItem(name, price, quantity, inStock = true) {
  return { name, price, quantity, inStock };
}

function itemSubtotal(item) {
  return item.price * item.quantity;
}

// ── Shopping Cart ────────────────────────────────────────────────

class ShoppingCart {
  constructor() {
    this.items = [];
    this.shipping = null;
  }

  // ── Item operations ──

  addItem(item) {
    const existing = this.items.find((i) => i.name === item.name);
    if (existing) {
      existing.quantity += item.quantity;
      console.log(`  ✔ Updated '${item.name}' quantity to ${existing.quantity}`);
      return;
    }
    this.items.push(item);
    console.log(`  ✔ Added '${item.name}' (x${item.quantity}) — $${item.price.toFixed(2)} each`);
  }

  removeItem(name) {
    const idx = this.items.findIndex((i) => i.name === name);
    if (idx === -1) {
      console.log(`  ⚠ Item '${name}' not found in cart`);
      return;
    }
    this.items.splice(idx, 1);
    console.log(`  ✖ Removed '${name}' from cart`);
  }

  updateQuantity(name, quantity) {
    const item = this.items.find((i) => i.name === name);
    if (!item) {
      console.log(`  ⚠ Item '${name}' not found in cart`);
      return;
    }
    const oldQty = item.quantity;
    item.quantity = quantity;
    console.log(`  ✔ Updated '${name}' quantity: ${oldQty} → ${quantity}`);
  }

  // ── Out-of-stock handling ──

  removeOutOfStock() {
    const outOfStock = this.items.filter((i) => !i.inStock);
    if (outOfStock.length === 0) {
      console.log("  ✔ All items are in stock!");
      return;
    }
    for (const item of outOfStock) {
      console.log(`  ✖ Removing out-of-stock item: '${item.name}'`);
      this.items.splice(this.items.indexOf(item), 1);
    }
    console.log(`  → Removed ${outOfStock.length} out-of-stock item(s)`);
  }

  // ── Shipping ──

  selectShipping(method) {
    this.shipping = method;
    console.log(`  ✔ Selected: ${method.description} — $${method.cost.toFixed(2)}`);
  }

  static showShippingOptions() {
    console.log("\n  Available Shipping Options:");
    console.log("  " + "─".repeat(55));
    let i = 1;
    for (const key of Object.keys(ShippingMethods)) {
      const m = ShippingMethods[key];
      console.log(`    ${i}. ${m.description.padEnd(45)} $${m.cost.toFixed(2).padStart(6)}`);
      i++;
    }
  }

  // ── Totals & Summary ──

  get itemsTotal() {
    return this.items.reduce((sum, item) => sum + itemSubtotal(item), 0);
  }

  get shippingCost() {
    return this.shipping ? this.shipping.cost : 0;
  }

  get orderTotal() {
    return this.itemsTotal + this.shippingCost;
  }

  showSummary() {
    const w = 58;
    console.log();
    console.log("  ╔" + "═".repeat(w) + "╗");
    console.log("  ║" + "ORDER SUMMARY".padStart(36).padEnd(w) + "║");
    console.log("  ╠" + "═".repeat(w) + "╣");

    if (this.items.length === 0) {
      console.log("  ║" + "  Cart is empty!".padEnd(w) + "║");
    } else {
      for (const item of this.items) {
        const stock = item.inStock ? "✔" : "✖ OUT OF STOCK";
        const desc = `  ${item.name} (x${item.quantity})`;
        const price = `$${itemSubtotal(item).toFixed(2)}`;
        const line = `${desc.padEnd(38)} ${price.padStart(8)}  ${stock}`;
        console.log("  ║" + line.padEnd(w) + "║");
      }
    }

    console.log("  ╠" + "═".repeat(w) + "╣");
    const subtotalLine = `  Items Subtotal:`.padEnd(42) + `$${this.itemsTotal.toFixed(2).padStart(7)}`;
    console.log("  ║" + subtotalLine.padEnd(w) + "║");

    if (this.shipping) {
      const shipLine = `  ${this.shipping.description}`.padEnd(42) + `$${this.shippingCost.toFixed(2).padStart(7)}`;
      console.log("  ║" + shipLine.padEnd(w) + "║");
    } else {
      const shipLine = `  Shipping: (not selected)`.padEnd(42) + `${"---".padStart(10)}`;
      console.log("  ║" + shipLine.padEnd(w) + "║");
    }

    console.log("  ╠" + "═".repeat(w) + "╣");
    const totalLine = `  ORDER TOTAL:`.padEnd(42) + `$${this.orderTotal.toFixed(2).padStart(7)}`;
    console.log("  ║" + totalLine.padEnd(w) + "║");
    console.log("  ╚" + "═".repeat(w) + "╝");
  }
}

// ── Run Simulation ───────────────────────────────────────────────

function main() {
  const cart = new ShoppingCart();

  // Step 1: Add items to cart
  console.log("\n📦 Step 1: Adding items to cart...");
  cart.addItem(createItem("Wireless Headphones",    59.99, 1, true));
  cart.addItem(createItem("USB-C Charging Cable",   12.99, 2, true));
  cart.addItem(createItem("Phone Case (Limited Ed.)", 29.99, 1, false));  // out of stock!
  cart.addItem(createItem("Screen Protector",        8.99, 3, true));

  // Step 2: Show initial cart
  console.log("\n📋 Step 2: Reviewing cart...");
  cart.showSummary();

  // Step 3: Browse shipping options
  console.log("\n🚚 Step 3: Browsing shipping options...");
  ShoppingCart.showShippingOptions();

  // Step 4: Select a shipping method
  console.log("\n🚚 Step 4: Selecting shipping method...");
  cart.selectShipping(ShippingMethods.EXPRESS);

  // Step 5: Remove out-of-stock items
  console.log("\n🔍 Step 5: Checking for out-of-stock items...");
  cart.removeOutOfStock();

  // Step 6: Update an item quantity
  console.log("\n✏️  Step 6: Updating item quantity...");
  cart.updateQuantity("USB-C Charging Cable", 1);

  // Step 7: Show final summary
  console.log("\n📋 Step 7: Final order summary...");
  cart.showSummary();
}

main();

